counter.source:
import { useState } from "react";

const Loading = () => <p>Loading…</p>;

const Button = ({ onClick, children }: { onClick: () => void; children: React.ReactNode }) => (
  <button onClick={onClick}>{children}</button>
);

export const App = ({ isLoading }: { isLoading: boolean }) => {
  const [count, setCount] = useState(0);
  return isLoading ? <Loading /> : <Button onClick={() => setCount(count + 1)}>{count}</Button>;
};

guards.source:
import { useState } from "react";

export const Composer = () => {
  const [draft, setDraft] = useState("");
  const [isSent, setIsSent] = useState(false);
  const send = () => {
    if (!draft) return;
    setIsSent(true);
  };
  if (isSent) return <p>Sent</p>;
  return (
    <div>
      <input value={draft} onChange={(event) => setDraft(event.target.value)} />
      <button onClick={send}>Send</button>
    </div>
  );
};

reducer.source:
import { useReducer } from "react";

interface WizardState {
  step: "details" | "payment" | "done";
  hasError: boolean;
}

type WizardAction = { type: "next" } | { type: "back" } | { type: "fail" };

const reducer = (state: WizardState, action: WizardAction): WizardState => {
  switch (action.type) {
    case "next":
      return { step: state.step === "details" ? "payment" : "done", hasError: false };
    case "back":
      return { ...state, step: "details" };
    case "fail":
      return { ...state, hasError: true };
  }
};

export const Wizard = () => {
  const [state, dispatch] = useReducer(reducer, { step: "details", hasError: false });
  if (state.step === "done") return <p>Thanks!</p>;
  return (
    <form>
      {state.hasError && <p role="alert">Something went wrong</p>}
      {state.step === "details" ? <input name="name" /> : <input name="card" />}
      {state.step === "payment" && (
        <button type="button" onClick={() => dispatch({ type: "back" })}>
          Back
        </button>
      )}
      <button type="button" onClick={() => dispatch({ type: "next" })}>
        Next
      </button>
    </form>
  );
};

dashboard.source:
import { useEffect, useState } from "react";

interface User {
  name: string;
}

interface Item {
  id: string;
  title: string;
}

const fetchItems = async (): Promise<Item[]> => [{ id: "1", title: "First" }];

const Spinner = () => <div className="spinner" />;
const SignIn = () => <a href="/login">Sign in</a>;
const Empty = () => <p>No items</p>;
const List = ({ items }: { items: Item[] }) => (
  <ul>
    {items.map((item) => (
      <li key={item.id}>{item.title}</li>
    ))}
  </ul>
);

export const Dashboard = ({
  status,
  user,
}: {
  status: "idle" | "loading" | "error";
  user: User | null;
}) => {
  const [count, setCount] = useState(0);
  const [items, setItems] = useState<Item[]>([]);
  useEffect(() => {
    fetchItems().then(setItems);
  }, []);
  if (status === "loading") return <Spinner />;
  if (!user) return <SignIn />;
  return (
    <main>
      <h1>{user.name}</h1>
      {items.length > 0 ? <List items={items} /> : <Empty />}
      <button onClick={() => setCount(count + 1)}>{count}</button>
    </main>
  );
};

todo.source:
import { useState } from "react";

interface Todo {
  id: number;
  text: string;
  isDone: boolean;
}

type Filter = "all" | "active" | "done";

export const TodoApp = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [draft, setDraft] = useState("");
  const [filter, setFilter] = useState<Filter>("all");
  const [isEditing, setIsEditing] = useState(false);

  const visibleTodos = todos.filter((todo) =>
    filter === "all" ? true : filter === "done" ? todo.isDone : !todo.isDone,
  );

  const addTodo = () => {
    if (!draft.trim()) return;
    setTodos([...todos, { id: Date.now(), text: draft, isDone: false }]);
    setDraft("");
  };

  return (
    <section>
      <input value={draft} onChange={(event) => setDraft(event.target.value)} />
      <button onClick={addTodo} disabled={draft === ""}>
        Add
      </button>
      {todos.length === 0 && <p>Nothing to do</p>}
      <ul>
        {visibleTodos.map((todo) => (
          <li
            key={todo.id}
            onClick={() =>
              setTodos(
                todos.map((other) =>
                  other.id === todo.id ? { ...other, isDone: !other.isDone } : other,
                ),
              )
            }
          >
            {todo.isDone ? <s>{todo.text}</s> : todo.text}
          </li>
        ))}
      </ul>
      <footer>
        <button onClick={() => setFilter("all")}>All</button>
        <button onClick={() => setFilter("active")}>Active</button>
        <button onClick={() => setFilter("done")}>Done</button>
      </footer>
      {isEditing ? (
        <button onClick={() => setIsEditing(false)}>Save</button>
      ) : (
        <button onClick={() => setIsEditing(true)}>Edit</button>
      )}
    </section>
  );
};

